def eulerian_number(n, m):
    if n < m or m < 0:
        return 0
    if n == m or m == 0:
        return 1
    dp = [[0] * (m+1) for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        dp[i][0] = i * dp[i-1][0]
        for j in range(1, m+1):
            dp[i][j] = dp[i-1][j-1] + (i * dp[i-1][j])
    return dp[n][m]
```

