import heapq

def merge_sorted_inputs(*inputs):
    iterators = []
    merged = []

    for it in inputs:
        if not isinstance(it, range) and not hasattr(it, '__iter__'):
            raise TypeError(f"Input {it} is not iterable")
        iterators.append(iter(it))

    heap = [(next(it), it) for it in iterators]
    heapq.heapify(heap)

    while heap:
        value, it = heap[0]
        merged.append(value)
        try:
            next_val = next(it)
            heapq.heapreplace(heap, (next_val, it))
        except StopIteration:
            heapq.heappop(heap)

    return iter(merged)
```

